                    onMouseOut={(e) => e.currentTarget.style.background = 'white'}
                  >
                    {num}
                  </button>
                ))}
                <button
                  type="button"
                  onClick={() => setTempCustomAmount('0')}
                  style={{
                    padding: '15px',
                    border: '1px solid #e1e8ed',
                    borderRadius: '8px',
                    background: 'white',
                    fontSize: '1rem',
                    cursor: 'pointer'
                  }}
                >
                  Clear
                </button>
                <button
                  type="button"
                  onClick={() => {
                    const newAmount = tempCustomAmount === '0' ? '0' : tempCustomAmount + '0';
                    if (parseInt(newAmount) <= bookingData.totalAmount) {
                      setTempCustomAmount(newAmount);
                    }
                  }}
                  style={{
                    padding: '15px',
                    border: '1px solid #e1e8ed',
                    borderRadius: '8px',
                    background: 'white',
                    fontSize: '1.2rem',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  0
                </button>
                <button
                  type="button"
                  onClick={() => {
                    if (tempCustomAmount.length > 1) {
                      setTempCustomAmount(tempCustomAmount.slice(0, -1));
                    } else {
                      setTempCustomAmount('0');
                    }
                  }}
                  style={{
                    padding: '15px',
                    border: '1px solid #e1e8ed',
                    borderRadius: '8px',
                    background: 'white',
                    fontSize: '1rem',
                    cursor: 'pointer'
                  }}
                >
                  ⌫
                </button>
              </div>

              <div style={{ display: 'flex', gap: '10px' }}>
                <button
                  type="button"
                  onClick={() => {
                    setShowCustomAmountPad(false);
                    setTempCustomAmount(bookingData.customAmount.toString());
                  }}
                  style={{
                    flex: 1,
                    padding: '12px',
                    border: '1px solid #ccc',
                    borderRadius: '8px',
                    background: 'white',
                    cursor: 'pointer'
                  }}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  onClick={() => {
                    const amount = Math.max(1000, Math.min(bookingData.totalAmount, parseInt(tempCustomAmount) || 1000));
                    setBookingData({ 
                      ...bookingData, 
                      customAmount: amount,
                      paymentType: 'custom',
                      paymentAmount: amount
                    });
                    setShowCustomAmountPad(false);
                  }}
                  disabled={parseInt(tempCustomAmount) < 1000 || parseInt(tempCustomAmount) > bookingData.totalAmount}
                  style={{
                    flex: 1,
                    padding: '12px',
                    border: 'none',
                    borderRadius: '8px',
                    background: (parseInt(tempCustomAmount) >= 1000 && parseInt(tempCustomAmount) <= bookingData.totalAmount) ? '#667eea' : '#ccc',
                    color: 'white',
                    cursor: (parseInt(tempCustomAmount) >= 1000 && parseInt(tempCustomAmount) <= bookingData.totalAmount) ? 'pointer' : 'not-allowed',
                    fontWeight: '600'
                  }}
                >
                  Confirm
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// Booking Page
const BookingPage: React.FC<{
  bookingData: BookingData;
  setBookingData: (data: BookingData) => void;
  onNext: () => void;
  onBack: () => void;
}> = ({ bookingData, setBookingData, onNext, onBack }) => {
  const [showCustomAmountPad, setShowCustomAmountPad] = useState(false);
  const [tempCustomAmount, setTempCustomAmount] = useState(bookingData.customAmount.toString());

  // Calculate total amount based on dates
  const calculateTotalAmount = (checkinDate: string, checkoutDate: string) => {
    if (!checkinDate || !checkoutDate) return 3500; // Default amount

    const checkin = new Date(checkinDate);
    const checkout = new Date(checkoutDate);
    const diffTime = Math.abs(checkout.getTime() - checkin.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    const baseRatePerDay = 500; // ₹500 per day
    return Math.max(1000, diffDays * baseRatePerDay); // Minimum ₹1000
  };

  // Update total amount when dates change
  React.useEffect(() => {
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      const newTotalAmount = calculateTotalAmount(bookingData.checkinDate, bookingData.checkoutDate);
      let newPaymentAmount = bookingData.paymentAmount;

      // Adjust payment amount based on current selection
      if (bookingData.paymentType === 'full') {
        newPaymentAmount = newTotalAmount;
      } else if (bookingData.paymentType === 'custom') {
        newPaymentAmount = Math.min(bookingData.customAmount, newTotalAmount);
      } else {
        newPaymentAmount = Math.min(1000, newTotalAmount); // Advance payment
      }

      setBookingData({ 
        ...bookingData, 
        totalAmount: newTotalAmount,
        paymentAmount: newPaymentAmount
      });
    }
  }, [bookingData.checkinDate, bookingData.checkoutDate]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (bookingData.checkinDate && bookingData.checkoutDate) {
      if (new Date(bookingData.checkinDate) >= new Date(bookingData.checkoutDate)) {
        alert('Check-out date must be after check-in date');
        return;
      }
      onNext();
    } else {
      alert('Please select both check-in and check-out dates');
    }
  };

  // Generate available dates (next 30 days)
  const getAvailableDates = () => {
    const dates = [];
    const today = new Date();
    for (let i = 0; i < 30; i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      dates.push(date.toISOString().split('T')[0]);
    }
    return dates;
  };

  const availableDates = getAvailableDates();

  return (
